 <div className="seller-sub-plan-grid">{recurringPlans.map((plan:any)=><article key={plan.id} className={'seller-sub-plan '+(plan.is_featured?'featured ':'')+(selected===plan.id?'selected':'')}><div className="seller-sub-plan-top"><div><h3>{plan.name}</h3><span>{plan.description||'Subscription plan'}</span></div>{plan.is_featured&&<span className="seller-sub-popular">POPULAR</span>}</div><div className="seller-sub-price"><strong>KSh {(Number(plan.price_minor||0)/100).toLocaleString('en-KE')}</strong><span>/ {Number(plan.interval_days)===30?'month':Number(plan.interval_days)===90?'3 months':Number(plan.interval_days)===180?'6 months':'year'}</span></div><div className="seller-sub-feature-heading">Everything included</div><ul><li><Check size={15}/>All DASMARKET features</li><li><Check size={15}/>Unlimited product listings</li><li><Check size={15}/>Full seller dashboard and tools</li><li><Check size={15}/>0% sales commission</li></ul><button type="button" className={selected===plan.id?'seller-sub-select selected':'seller-sub-select'} onClick={()=>{setError('');setMessage('');onCheckout(plan.id)}}>{selected===plan.id?'Selected plan':'Choose '+plan.name}</button></article>)}</div>
 {checkoutPlanId&&selected&&<section className="seller-sub-checkout-page"><div className="seller-sub-checkout-page-top"><button type="button" className="seller-secondary-btn" onClick={onBack}><ArrowLeft size={15}/> Back to subscription plans</button><span>SECURE BILLING</span></div><div className="seller-sub-checkout-modal seller-sub-checkout-standalone" role="region" aria-labelledby="seller-sub-checkout-title"><header><div><span>{plans.find((p:any)=>p.id===selected)?.code==='lifetime-license'?'ONE-TIME LICENCE CHECKOUT':'SUBSCRIPTION CHECKOUT'}</span><h3 id="seller-sub-checkout-title">{plans.find((p:any)=>p.id===selected)?.code==='lifetime-license'?'Lifetime platform licence':plans.find((p:any)=>p.id===selected)?.name||'Selected plan'}</h3></div></header><div className="seller-sub-checkout-plan"><strong>KSh {(Number(plans.find((p:any)=>p.id===selected)?.price_minor||0)/100).toLocaleString('en-KE')}</strong><span>{plans.find((p:any)=>p.id===selected)?.code==='lifetime-license'?'once · lifetime access':'/ '+(Number(plans.find((p:any)=>p.id===selected)?.interval_days)===30?'month':Number(plans.find((p:any)=>p.id===selected)?.interval_days)===90?'3 months':Number(plans.find((p:any)=>p.id===selected)?.interval_days)===180?'6 months':'year')}</span><small>{plans.find((p:any)=>p.id===selected)?.description||'Subscription plan'}</small></div><label>M-PESA phone number<input type="tel" inputMode="tel" autoComplete="tel" placeholder="07XXXXXXXX or 2547XXXXXXXX" value={mobile} onChange={e=>setMobile(e.target.value)}/></label><div className="seller-sub-billing-email"><label>Billing email for card payments<input type="email" autoComplete="email" required placeholder="billing@yourshop.co.ke" value={billingEmail} onChange={e=>setBillingEmail(e.target.value)}/><small>Used for DASMARKET subscription receipts. Saved separately for this shop; it does not change your login email.</small></label><button type="button" className="seller-secondary-btn" disabled={billingSaving||!billingEmail.trim()} onClick={saveBillingEmail}>{billingSaving?"Saving…":"Save billing email"}</button></div><button type="button" className="seller-sub-pay-button" disabled={!selected||sending||!data?.payment?.configured} onClick={pay}>{sending?'Sending prompt…':plans.find((p:any)=>p.id===selected)?.code==='lifetime-license'?'Pay once with M-PESA':'Pay with M-PESA'}</button><button type="button" className="seller-sub-pay-button" disabled={!selected||sending} onClick={payCard}>{sending?'Opening secure checkout…':'Pay with Card (Paystack)'}</button>{!data?.payment?.configured&&<p className="seller-sub-modal-warning">M-PESA subscription payment destination is not configured yet. Card subscription payments are collected by DASMARKET's central Paystack account; seller settlement KYC is not required for subscription fees.</p>}{error&&<div className="auth-message error">{error}</div>}{message&&<div className="auth-message success">{message}</div>}<p className="seller-sub-modal-note">Your access is activated only after the payment provider independently confirms the payment.</p></div></section>}
