 async function createSubaccount(e:any){e.preventDefault();setBusy(true);setError('');setNotice('');try{const r=await fetch('/api/merchant?action=paystack-subaccount',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(bank)}),d=await readApiResponse(r);if(!r.ok)throw Error(d.error||'Could not create settlement subaccount');setNotice(d.isVerified?'Paystack has verified the settlement subaccount. Card payments can be enabled.':'Subaccount created successfully. Paystack settlement verification is still pending; card payments remain disabled until Paystack confirms it.');await load();}catch(e:any){setError(e.message)}finally{setBusy(false)}}
  async function refreshSubaccountStatus(){setBusy(true);setError('');setNotice('');try{const r=await fetch('/api/merchant?action=paystack-subaccount-status',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({})}),d=await readApiResponse(r);if(!r.ok)throw Error(d.error||'Could not refresh Paystack settlement status');setNotice(d.isVerified?'Paystack confirms your settlement account is verified and active.':'Paystack has not verified this settlement account yet. Card checkout remains disabled until verification is complete.');await load();}catch(e:any){setError(e.message)}finally{setBusy(false)}}
