 async function uploadKycDocument(kind:string,file?:File){if(!file)return;setBusy(true);setError('');setNotice('');try{if(file.size>5242880)throw Error('Each document must be 5 MB or smaller.');const start=await fetch('/api/merchant?action=card-kyc-document-upload',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,fileName:file.name,contentType:file.type,size:file.size})}),d=await readApiResponse(start);if(!start.ok)throw Error(d.error||'Could not prepare document upload');const put=await fetch(d.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!put.ok)throw Error('Secure document upload failed. Please retry.');const confirm=await fetch('/api/merchant?action=card-kyc-document-confirm',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,objectKey:d.objectKey,contentType:file.type,size:file.size})}),done=await readApiResponse(confirm);if(!confirm.ok)throw Error(done.error||'Could not verify uploaded document');setNotice('Document uploaded and verified securely.');await load();}catch(e:any){setError(e.message)}finally{setBusy(false)}}
